<?php
/** Two-person full database restore and rollback helpers. */
require_once __DIR__ . '/database_restore_preview.php';
require_once __DIR__ . '/database_backup_launcher.php';
require_once __DIR__ . '/settings.php';

function get_database_live_restore_job(PDO $pdo, int $jobId): ?array
{
    $stmt=$pdo->prepare('SELECT l.*,p.backup_job_id,p.status AS preview_status,p.staging_database_name,p.report_path,p.table_statements,p.staging_table_count,b.database_name AS source_database_name_from_backup,b.status AS source_backup_status,b.dump_path AS source_dump_path,pb.status AS pre_backup_status,pb.dump_path AS pre_backup_dump_path,pb.backup_folder AS pre_backup_folder FROM database_live_restore_jobs l JOIN database_restore_preview_jobs p ON p.id=l.preview_job_id JOIN database_backup_jobs b ON b.id=p.backup_job_id LEFT JOIN database_backup_jobs pb ON pb.id=l.pre_restore_backup_job_id WHERE l.id=:id LIMIT 1');$stmt->execute([':id'=>$jobId]);$row=$stmt->fetch(PDO::FETCH_ASSOC);return$row?:null;
}
function database_live_restore_approvals(PDO $pdo,int $jobId,?string $action=null):array{$where='a.job_id=:job_id';$params=[':job_id'=>$jobId];if($action!==null){$where.=' AND a.action=:action';$params[':action']=$action;}$stmt=$pdo->prepare('SELECT a.action,a.stage,a.user_id,a.created_at,u.username,u.full_name FROM database_live_restore_approvals a LEFT JOIN users u ON u.id=a.user_id WHERE '.$where.' ORDER BY a.action,a.stage');$stmt->execute($params);return$stmt->fetchAll(PDO::FETCH_ASSOC);}
function database_live_restore_log(PDO $pdo,int $jobId,string $level,string $message):void{$stmt=$pdo->prepare('INSERT INTO database_live_restore_logs (job_id,level,message) VALUES (:job_id,:level,:message)');$stmt->execute([':job_id'=>$jobId,':level'=>$level,':message'=>mb_substr($message,0,1000)]);}
function database_live_restore_logs(PDO $pdo,int $jobId,int $limit=100):array{$stmt=$pdo->prepare('SELECT id,level,message,created_at FROM database_live_restore_logs WHERE job_id=:job_id ORDER BY id DESC LIMIT :limit');$stmt->bindValue(':job_id',$jobId,PDO::PARAM_INT);$stmt->bindValue(':limit',max(1,min(500,$limit)),PDO::PARAM_INT);$stmt->execute();return$stmt->fetchAll(PDO::FETCH_ASSOC);}
function update_database_live_restore_job(PDO $pdo,int $jobId,string $status,array $fields=[]):void{$allowed=['pre_restore_backup_job_id','last_error','started_at','last_activity_at','completed_at','target_table_count','expected_table_count'];$sets=['status=:status','last_activity_at=NOW()'];$params=[':status'=>$status,':id'=>$jobId];foreach($allowed as $field)if(array_key_exists($field,$fields)){$sets[]="{$field}=:{$field}";$params[":{$field}"]=$fields[$field];}if(in_array($status,['running','rolling_back'],true))$sets[]='started_at=COALESCE(started_at,NOW())';if(in_array($status,['completed','completed_with_errors','failed','cancelled','rolled_back'],true))$sets[]='completed_at=COALESCE(completed_at,NOW())';$stmt=$pdo->prepare('UPDATE database_live_restore_jobs SET '.implode(',',$sets).' WHERE id=:id');$stmt->execute($params);}
function database_live_restore_assert_preview(array $preview):void{if(!in_array((string)($preview['status']??''),['completed','completed_with_errors','cleaned'],true))throw new RuntimeException('The restore preview must complete before a live database restore can be prepared.');if((int)($preview['table_statements']??0)<=0||(int)($preview['staging_table_count']??0)<=0)throw new RuntimeException('The restore preview has no verified database tables.');if(!is_file((string)($preview['dump_path']??''))||!is_file((string)($preview['manifest_path']??'')))throw new RuntimeException('The verified database dump or manifest is unavailable.');}
function create_database_live_restore_job(PDO $pdo,int $previewJobId,string $backupRoot,string $backupFolder,?int $userId=null):int{$preview=get_database_restore_preview_job($pdo,$previewJobId);if(!$preview)throw new RuntimeException('Restore preview job not found.');database_live_restore_assert_preview($preview);$verification=verify_database_backup_job($pdo,(int)$preview['backup_job_id']);if(empty($verification['valid']))throw new RuntimeException('The source database backup failed hash verification.');$existing=$pdo->prepare('SELECT id,status FROM database_live_restore_jobs WHERE preview_job_id=:preview_job_id LIMIT 1');$existing->execute([':preview_job_id'=>$previewJobId]);if($existing->fetch())throw new RuntimeException('A live database restore plan already exists for this preview. Review that plan before creating another one.');$pdo->beginTransaction();try{$stmt=$pdo->prepare('INSERT INTO database_live_restore_jobs (preview_job_id,status,source_database_name,target_database_name,target_database_host,created_by,expected_table_count,last_activity_at) VALUES (:preview_job_id,\'backup_running\',:source_database_name,:target_database_name,:target_database_host,:created_by,:expected_table_count,NOW())');$stmt->execute([':preview_job_id'=>$previewJobId,':source_database_name'=>$preview['database_name'],':target_database_name'=>DB_NAME,':target_database_host'=>DB_HOST,':created_by'=>$userId,':expected_table_count'=>(int)$preview['staging_table_count']]);$jobId=(int)$pdo->lastInsertId();$backupId=create_database_backup_job($pdo,$backupRoot,$backupFolder,$userId);$update=$pdo->prepare('UPDATE database_live_restore_jobs SET pre_restore_backup_job_id=:backup_id WHERE id=:id');$update->execute([':backup_id'=>$backupId,':id'=>$jobId]);database_live_restore_log($pdo,$jobId,'info','Full database restore plan created; pre-restore backup started.');$pdo->commit();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw$e;}return$jobId;}
function database_live_restore_sync_job(PDO $pdo,int $jobId):array{$job=get_database_live_restore_job($pdo,$jobId);if(!$job)throw new RuntimeException('Live database restore job not found.');if((string)$job['status']==='backup_running'){$backupId=(int)$job['pre_restore_backup_job_id'];$backup=$backupId>0?get_database_backup_job($pdo,$backupId):null;if($backup&&(string)$backup['status']==='completed'){$verification=verify_database_backup_job($pdo,$backupId);if(empty($verification['valid'])){update_database_live_restore_job($pdo,$jobId,'failed',['last_error'=>'Pre-restore backup hash verification failed.']);database_live_restore_log($pdo,$jobId,'error','Pre-restore backup verification failed.');}else{update_database_live_restore_job($pdo,$jobId,'awaiting_approval',['last_error'=>null]);database_live_restore_log($pdo,$jobId,'info','Pre-restore backup verified; two restore approvals are required.');}}elseif($backup&&in_array((string)$backup['status'],['failed','cancelled'],true)){update_database_live_restore_job($pdo,$jobId,'failed',['last_error'=>'Pre-restore backup did not complete: '.$backup['status']]);database_live_restore_log($pdo,$jobId,'error','Pre-restore backup failed or was cancelled.');}}return get_database_live_restore_job($pdo,$jobId)?:$job;}
function database_live_restore_maintenance_enabled():bool{return function_exists('maintenance_is_active')?maintenance_is_active():(function_exists('get_setting')&&(bool)get_setting('maintenance_mode',false));}
function database_live_restore_approve(PDO $pdo,int $jobId,string $action,int $stage,int $userId):array{if(!in_array($action,['restore','rollback'],true)||!in_array($stage,[1,2],true)||$userId<=0)throw new InvalidArgumentException('A valid database restore action, approval stage, and administrator are required.');$job=database_live_restore_sync_job($pdo,$jobId);$status=(string)$job['status'];if($action==='restore'&&$status!=='awaiting_approval')throw new RuntimeException('The database restore is not awaiting approval.');if($action==='rollback'&&!in_array($status,['completed','completed_with_errors','failed'],true))throw new RuntimeException('Rollback is available only after a finished restore.');if(!database_live_restore_maintenance_enabled())throw new RuntimeException('Enable Maintenance Mode before approving a live database operation.');$preview=get_database_restore_preview_job($pdo,(int)$job['preview_job_id']);if(!$preview)throw new RuntimeException('The restore preview is no longer available.');database_live_restore_assert_preview($preview);$sourceVerification=verify_database_backup_job($pdo,(int)$preview['backup_job_id']);if(empty($sourceVerification['valid']))throw new RuntimeException('The source database backup is not verified.');$preVerification=verify_database_backup_job($pdo,(int)$job['pre_restore_backup_job_id']);if(empty($preVerification['valid']))throw new RuntimeException('The pre-restore rollback backup is not verified.');$approvals=database_live_restore_approvals($pdo,$jobId,$action);$byStage=[];foreach($approvals as $approval)$byStage[(int)$approval['stage']]=$approval;if(isset($byStage[$stage]))throw new RuntimeException('This approval stage is already recorded.');if($stage===1&&(int)$job['created_by']===$userId)throw new RuntimeException('The creator cannot provide the first independent approval.');if($stage===2){if(!isset($byStage[1]))throw new RuntimeException('The first approval is required before the second approval.');if((int)$byStage[1]['user_id']===$userId)throw new RuntimeException('The second approval must come from a different administrator.');}$pdo->beginTransaction();try{$insert=$pdo->prepare('INSERT INTO database_live_restore_approvals (job_id,action,stage,user_id) VALUES (:job_id,:action,:stage,:user_id)');$insert->execute([':job_id'=>$jobId,':action'=>$action,':stage'=>$stage,':user_id'=>$userId]);if($action==='restore'){if($stage===1){database_live_restore_log($pdo,$jobId,'info','First full database restore approval recorded.');$message='First restore approval recorded; a different administrator must approve Stage 2.';}else{update_database_live_restore_job($pdo,$jobId,'approved',['last_error'=>null]);database_live_restore_log($pdo,$jobId,'info','Second restore approval recorded; full database replacement will start.');$message='Second restore approval recorded; live database replacement will start.';}}else{if($stage===1){update_database_live_restore_job($pdo,$jobId,'rollback_awaiting_approval');database_live_restore_log($pdo,$jobId,'warning','First rollback approval recorded.');$message='First rollback approval recorded; a different administrator must approve Stage 2.';}else{update_database_live_restore_job($pdo,$jobId,'rolling_back');database_live_restore_log($pdo,$jobId,'warning','Second rollback approval recorded; rollback replacement will start.');$message='Second rollback approval recorded; rollback will start.';}}$pdo->commit();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw$e;}if($stage===2){try{launch_database_live_restore_worker($jobId,$action);}catch(Throwable $e){update_database_live_restore_job($pdo,$jobId,'failed',['last_error'=>$e->getMessage()]);database_live_restore_log($pdo,$jobId,'error','Approval was recorded but the database worker could not start: '.$e->getMessage());throw$e;}}return['job'=>get_database_live_restore_job($pdo,$jobId)?:$job,'message'=>$message];}
function database_live_restore_cancel(PDO $pdo,int $jobId,int $userId):array{$job=database_live_restore_sync_job($pdo,$jobId);if(in_array((string)$job['status'],['completed','completed_with_errors','failed','cancelled','rolled_back','running','rolling_back'],true))throw new RuntimeException('This database restore job cannot be cancelled at its current stage.');update_database_live_restore_job($pdo,$jobId,'cancelled',['last_error'=>'Cancelled by administrator #'.$userId]);database_live_restore_log($pdo,$jobId,'warning','Database restore plan cancelled by administrator.');return get_database_live_restore_job($pdo,$jobId)?:$job;}
function database_live_restore_capture_rows(PDO $pdo,string $table,string $column,array $values):array{$values=array_values(array_unique(array_filter(array_map('intval',$values),static fn($v)=>$v>0)));if(!$values)return[];$marks=implode(',',array_fill(0,count($values),'?'));$stmt=$pdo->prepare('SELECT * FROM `'.$table.'` WHERE `'.$column.'` IN ('.$marks.')');$stmt->execute($values);return$stmt->fetchAll(PDO::FETCH_ASSOC);}
function database_live_restore_control_snapshot(PDO $pdo,int $jobId,array $job,array $preview):array{$backupIds=[(int)$preview['backup_job_id'],(int)$job['pre_restore_backup_job_id']];$snapshot=[];$snapshot['database_backup_jobs']=database_live_restore_capture_rows($pdo,'database_backup_jobs','id',$backupIds);$snapshot['database_backup_job_logs']=database_live_restore_capture_rows($pdo,'database_backup_job_logs','job_id',$backupIds);$snapshot['database_restore_preview_jobs']=database_live_restore_capture_rows($pdo,'database_restore_preview_jobs','id',[(int)$job['preview_job_id']]);$snapshot['database_restore_preview_logs']=database_live_restore_capture_rows($pdo,'database_restore_preview_logs','job_id',[(int)$job['preview_job_id']]);$snapshot['database_live_restore_jobs']=database_live_restore_capture_rows($pdo,'database_live_restore_jobs','id',$jobId?[$jobId]:[]);$snapshot['database_live_restore_approvals']=database_live_restore_capture_rows($pdo,'database_live_restore_approvals','job_id',[$jobId]);$snapshot['database_live_restore_logs']=database_live_restore_capture_rows($pdo,'database_live_restore_logs','job_id',[$jobId]);return$snapshot;}
function database_live_restore_apply_schema(PDO $pdo):void{$migrations=['040_pdf_fingerprint_registry.sql','041_pdf_protection_jobs.sql','042_pdf_fingerprint_triggers.sql','043_pdf_fingerprint_trigger_release_fix.sql','044_pdf_fingerprint_owner_index_fix.sql','045_database_backup_jobs.sql','046_database_restore_preview_jobs.sql','047_production_restore_control_jobs.sql','048_pdf_protection_dry_run_flag.sql','049_database_live_restore_jobs.sql'];$pdo->exec('CREATE TABLE IF NOT EXISTS migrations (id INT AUTO_INCREMENT PRIMARY KEY,migration_name VARCHAR(255) NOT NULL UNIQUE,executed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4');$done=array_flip($pdo->query('SELECT migration_name FROM migrations')->fetchAll(PDO::FETCH_COLUMN));foreach($migrations as $migration){if(isset($done[$migration]))continue;$path=BASE_PATH.DIRECTORY_SEPARATOR.'database'.DIRECTORY_SEPARATOR.'migrations'.DIRECTORY_SEPARATOR.$migration;if(!is_file($path))throw new RuntimeException('Required restore schema migration is missing: '.$migration);$pdo->exec(file_get_contents($path));$stmt=$pdo->prepare('INSERT INTO migrations (migration_name) VALUES (?)');$stmt->execute([$migration]);}}
function database_live_restore_upsert_rows(PDO $pdo,string $table,array $rows):void{foreach($rows as $row){if(!$row)continue;$columns=array_keys($row);$quoted=array_map(static fn($column)=>'`'.$column.'`',$columns);$marks=array_map(static fn($column)=>':v_'.$column,$columns);$updates=[];foreach($columns as $column)if($column!=='id')$updates[]='`'.$column.'`=VALUES(`'.$column.'`)';$sql='INSERT INTO `'.$table.'` ('.implode(',',$quoted).') VALUES ('.implode(',',$marks).')';if($updates)$sql.=' ON DUPLICATE KEY UPDATE '.implode(',',$updates);$stmt=$pdo->prepare($sql);$params=[];foreach($columns as $column)$params[':v_'.$column]=$row[$column];$stmt->execute($params);}}
function database_live_restore_restore_control_snapshot(PDO $pdo,array $snapshot):void{database_live_restore_apply_schema($pdo);foreach(['database_backup_jobs','database_backup_job_logs','database_restore_preview_jobs','database_restore_preview_logs','database_live_restore_jobs','database_live_restore_approvals','database_live_restore_logs'] as $table)database_live_restore_upsert_rows($pdo,$table,$snapshot[$table]??[]);}
function database_live_restore_replace_target(PDO $pdo,string $temporaryDump,array $snapshot):array{$target=database_restore_preview_identifier(DB_NAME);$adminPdo=new PDO('mysql:host='.DB_HOST.';charset=utf8mb4',DB_USER,DB_PASS,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);$adminPdo->exec('DROP DATABASE IF EXISTS '.$target);$adminPdo->exec('CREATE DATABASE '.$target.' CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci');$pdo->exec('USE '.$target);try{$result=database_restore_preview_process(database_restore_preview_mysql_command(DB_NAME),$temporaryDump);if((int)$result['exit_code']!==0)throw new RuntimeException('Live database replacement failed: '.($result['stderr']?:$result['stdout']));database_live_restore_restore_control_snapshot($pdo,$snapshot);return$result;}catch(Throwable $e){try{database_live_restore_restore_control_snapshot($pdo,$snapshot);}catch(Throwable $restoreError){throw new RuntimeException($e->getMessage().' Control-table recovery also failed: '.$restoreError->getMessage(),0,$e);}throw$e;}}
function database_live_restore_run(PDO $pdo,int $jobId,string $action):array{$job=get_database_live_restore_job($pdo,$jobId);if(!$job)throw new RuntimeException('Live database restore job not found.');if($action==='restore'&&(string)$job['status']!=='approved')throw new RuntimeException('Restore worker is not approved.');if($action==='rollback'&&(string)$job['status']!=='rolling_back')throw new RuntimeException('Rollback worker is not approved.');if(!database_live_restore_maintenance_enabled())throw new RuntimeException('Maintenance Mode must remain enabled during the live database operation.');$preview=get_database_restore_preview_job($pdo,(int)$job['preview_job_id']);if(!$preview)throw new RuntimeException('The restore preview is no longer available.');$sourceBackupId=$action==='rollback'?(int)$job['pre_restore_backup_job_id']:(int)$preview['backup_job_id'];$sourceBackup=get_database_backup_job($pdo,$sourceBackupId);if(!$sourceBackup||(string)$sourceBackup['status']!=='completed')throw new RuntimeException('The selected database dump is not complete.');$verification=verify_database_backup_job($pdo,$sourceBackupId);if(empty($verification['valid']))throw new RuntimeException('The selected database dump failed hash verification.');$snapshot=database_live_restore_control_snapshot($pdo,$jobId,$job,$preview);$temp=database_restore_preview_normalize_dump((string)$sourceBackup['dump_path'],(string)$sourceBackup['database_name'],DB_NAME);try{if($action==='restore')update_database_live_restore_job($pdo,$jobId,'running');$result=database_live_restore_replace_target($pdo,$temp,$snapshot);$tableStmt=$pdo->prepare("SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=:schema AND table_type='BASE TABLE'");$tableStmt->execute([':schema'=>DB_NAME]);$tableCount=(int)$tableStmt->fetchColumn();$expected=(int)($action==='restore'?$job['expected_table_count']:0);$status=$action==='rollback'?'rolled_back':($expected>0&&$tableCount<$expected?'completed_with_errors':'completed');update_database_live_restore_job($pdo,$jobId,$status,['target_table_count'=>$tableCount,'last_error'=>null]);database_live_restore_log($pdo,$jobId,$status==='completed'?'info':($status==='rolled_back'?'warning':'warning'),$action==='rollback'?'Rollback database replacement completed.':'Live database replacement completed.');return get_database_live_restore_job($pdo,$jobId)?:$job;}finally{if(is_file($temp))@unlink($temp);}}
